const { chromium } = require('/home/vscode/.pwverify/node_modules/playwright');
(async () => {
  const b = await chromium.launch({ executablePath:'/usr/bin/chromium', headless:true, args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage'] });
  const page = await b.newPage({ viewport:{width:1400,height:1000} });
  await page.goto('http://127.0.0.1:8088/p/f8093eb9/', { waitUntil:'domcontentloaded', timeout:20000 });
  await page.waitForTimeout(2000);
  await page.evaluate(()=>openPlanDetail('plan-6ee9b0c8','verify'));
  await page.waitForSelector('#plan-detail-body .slice-card',{state:'attached',timeout:15000});
  await page.waitForTimeout(2000);
  const r = await page.evaluate(() => {
    const card=document.querySelector('#plan-detail-body .slice-card');
    const radio=card.querySelector('.seg-btn input[type=radio]');
    const cs=radio?getComputedStyle(radio):null;
    let hideRule=false, escaped=false;
    for (const ss of document.styleSheets){try{for(const ru of ss.cssRules){const t=ru.cssText||'';if(t.includes('.seg-btn input'))hideRule=true;if(t.includes('&#34;')||t.includes('&amp;'))escaped=true;}}catch(e){}}
    const seg=card.querySelector('.approval-segmented');
    return {radioHidden: cs?(cs.opacity==='0'||cs.position==='absolute'||cs.width==='0px'):null, radioCS:cs?{opacity:cs.opacity,position:cs.position,width:cs.width}:null, segHideRulePresent:hideRule, anyEscapedEntityInCSS:escaped, hasSegmented:!!seg};
  });
  console.log(JSON.stringify(r,null,2));
  // screenshot the card region
  await page.evaluate(()=>{const s=document.querySelector('#plan-detail-body .slice-card');if(s){if(s.tagName==='DETAILS')s.open=true; s.scrollIntoView({block:'center'});}});
  await page.waitForTimeout(600);
  await page.screenshot({path:'/home/vscode/.pwverify/card.png',fullPage:false});
  console.log('SHOT_SAVED');
  await b.close();
})().catch(e=>{console.log('FATAL',e.message);process.exit(1);});
EOF
