cat > /home/vscode/.pwverify/jserr.js <<'EOF'
const { chromium } = require('/home/vscode/.pwverify/node_modules/playwright');
(async () => {
  const b = await chromium.launch({ executablePath:'/usr/bin/chromium', headless:true, args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage'] });
  const page = await b.newPage({ viewport:{width:1400,height:1000} });
  const errs=[];
  page.on('pageerror', e=>errs.push('PAGEERROR: '+e.message));
  page.on('console', m=>{ if(m.type()==='error') errs.push('CONSOLE.ERR: '+m.text()); });
  await page.goto('http://127.0.0.1:8088/p/f8093eb9/', { waitUntil:'domcontentloaded', timeout:20000 });
  await page.waitForTimeout(4000);
  // is the activity feed populated?
  const state = await page.evaluate(()=>{
    const feed=document.querySelector('#v-activity, .activity-feed, [class*=activity]');
    const rows=document.querySelectorAll('[class*=feed] [class*=row], .activity-row, #v-activity tr, #v-activity li').length;
    return { bodyTextLen: document.body.innerText.length, activityRows: rows, hasLoadingOrEmpty: /Loading|No data|empty/i.test(document.body.innerText.slice(0,2000)) };
  });
  console.log('STATE:', JSON.stringify(state));
  console.log('ERRORS('+errs.length+'):'); errs.slice(0,12).forEach(e=>console.log('  '+e));
  await b.close();
})().catch(e=>{console.log('FATAL',e.message);process.exit(1);});
EOF
