const { chromium } = require('/home/vscode/.pwverify/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  page.on('console', msg => {
    if (msg.type() !== 'log') console.log('CONSOLE [' + msg.type() + ']:', msg.text());
  });

  await page.goto('http://127.0.0.1:8088/p/f8093eb9/');
  await page.waitForTimeout(7000);

  // Directly call render and check what happens
  const result = await page.evaluate(() => {
    var tree = document.querySelector('hg-event-tree');
    if (!tree) return { error: 'no element' };

    // Check before render
    var turnCount = tree.turns ? tree.turns.length : 0;
    var filters = tree.getFilterValues ? tree.getFilterValues() : null;

    // Try getting first turn rendered HTML
    var firstTurnHtml = '';
    if (tree.turns && tree.turns.length > 0 && tree.renderTurn) {
      try {
        firstTurnHtml = tree.renderTurn(tree.turns[0]).substring(0, 200);
      } catch(e) {
        firstTurnHtml = 'ERROR: ' + e.message;
      }
    }

    // Try rendering
    if (tree.render) {
      try {
        tree.render();
      } catch(e) {
        return { renderError: e.message };
      }
    }

    return {
      turnCount,
      filters,
      firstTurnHtml,
      innerHTMLAfterRender: tree.innerHTML.substring(0, 300),
      innerHTMLLength: tree.innerHTML.length,
    };
  });
  console.log('Result:', JSON.stringify(result, null, 2));

  await browser.close();
})().catch(err => { console.error(err); process.exit(1); });
